/** Offline fixture author/verifier only. Never embedded in a client save or gameplay JAR. */
public final class ExpandedContainerField extends JavaPlugin {
 public ExpandedContainerField(JavaPluginInit init){super(init);}
 record Station(String role,String family,String color,int x,int z){Vector3d pad(){return new Vector3d(x,64,z-.5);}Vector3d npc(){return new Vector3d(x,64,z+7.5);}}
 static final Set<String> OLD=Set.of("Kweebec_Sapling_HyThiefWitness","Feran_Civilian_HyThiefWitness","Kweebec_Razorleaf","Feran_Sharptooth");
 World w;Store<EntityStore>s;List<Station>stations=new ArrayList<>();List<String>evidence=new ArrayList<>();Map<String,Ref<EntityStore>>roles=new HashMap<>(),peers=new HashMap<>();String mode=System.getProperty("field.mode","verify");
 Ref<EntityStore>actor;Station selected;int ticks;float healthBefore;boolean combat; double maxIdleDistance,maxIdleYaw,maxCombatDistance; Set<String> idleStates=new TreeSet<>(); boolean peerReacted,primaryReacted,peerAcquired,peerAroundWall;double peerMaxDistance,primaryMaxDistance;int primaryFirst=-1,peerFirst=-1;String previousPrimary="",previousPeer="";
 void out(String text){evidence.add(text);System.out.println("EXPANDED_FIELD "+text);}
 static void require(boolean ok,String message){if(!ok)throw new IllegalStateException(message);}
 protected void start(){Universe.get().getUniverseReady().thenRun(()->{w=Universe.get().getDefaultWorld();var loads=new ArrayList<CompletableFuture<?>>();for(int x=-2;x<=1;x++)for(int z=-1;z<=3;z++)for(int y=1;y<=2;y++)loads.add(w.getChunkStore().getChunkSectionReferenceAsync(x,y,z,GetChunkFlags.SET_TICKING));CompletableFuture.allOf(loads.toArray(CompletableFuture[]::new)).thenRun(()->w.execute(()->{try{init();}catch(Throwable e){fail(e);}}));});}
 void index(){roles.clear();peers.clear();s.forEachChunk(NPCEntity.getComponentType(),(c,b)->{for(int i=0;i<c.size();i++){var r=c.getReferenceTo(i);String name=s.getComponent(r,NPCEntity.getComponentType()).getRoleName();var plate=s.getComponent(r,Nameplate.getComponentType());boolean isPeer=plate!=null&&plate.getText().startsWith("PEER - ");if(isPeer&&name.equals("Trork_Sentry"))name="Trork_Warrior";var map=isPeer?peers:roles;require(map.put(name,r)==null,"duplicate primary/peer role "+name);}});}
 Set<String>enabled(){var names=new HashSet<String>(Set.of("Kweebec_Sapling_HyThiefWitness","Feran_Civilian_HyThiefWitness"));for(var station:stations){names.add(station.role());names.add(peerRole(station));}return names;}
 void init()throws Exception{s=w.getEntityStore().getStore();for(var value:JsonParser.parseString(Files.readString(Path.of("passive-stations.json"))).getAsJsonArray()){var x=value.getAsJsonObject();stations.add(new Station(x.get("Role").getAsString(),x.get("Family").getAsString(),x.get("Color").getAsString(),x.get("X").getAsInt(),x.get("Z").getAsInt()));}index();for(int z:new int[]{-6,-2,2,6})ensureChest(0,z);
  if(mode.equals("peer-author")){require(!w.getWorldConfig().isTicking()&&roles.size()==9&&peers.isEmpty(),"author needs original nine NPC paused save");String before=primaryPoses();Files.writeString(Path.of("primary-poses.txt"),before);String original=snapshotOriginal();author();index();require(before.equals(primaryPoses()),"primary altered during author");require(original.equals(snapshotOriginal()),"original field altered");finish("PEER_AUTHOR_PASS");}
  else if(mode.equals("peer-verify")){require(!w.getWorldConfig().isTicking(),"verify paused");require(primaryPoses().equals(Files.readString(Path.of("primary-poses.txt"))),"saved primary identity/pose/state altered");require(snapshotOriginal().equals(Files.readString(Path.of("original-area.sha256"))),"old area altered");verify();finish("PEER_VERIFY_PASS");}
  else if(mode.equals("peer-idle")){for(var station:stations){var dummy=spawn("Test_Dummy_Stationary",station.pad());for(var ref:List.of(roles.get(station.role()),peers.get(station.role())))s.getComponent(ref,WorldSupport.getComponentType()).overrideAttitude(dummy,Attitude.FRIENDLY,600);}schedule();}
  else if(mode.startsWith("peer-response-")){selected=stations.stream().filter(x->x.role().equals(mode.substring(14))).findFirst().orElseThrow();actor=spawn("Test_Dummy_Stationary",selected.pad());var movement=new MovementStatesComponent();movement.setMovementStates(new com.hypixel.hytale.protocol.MovementStates());s.putComponent(actor,MovementStatesComponent.getComponentType(),movement);for(var ref:List.of(roles.get(selected.role()),peers.get(selected.role())))s.getComponent(ref,WorldSupport.getComponentType()).overrideAttitude(actor,Attitude.FRIENDLY,600);healthBefore=health();schedule();}
  else throw new IllegalArgumentException(mode);
 }
 String peerRole(Station station){return station.role().equals("Trork_Warrior")?"Trork_Sentry":station.role();}
 Vector3d peerPosition(Station station){return new Vector3d(station.npc()).add(6,0,0);}
 String primaryPoses(){var text=new StringBuilder();for(var name:new TreeSet<>(roles.keySet())){var ref=roles.get(name);text.append(name).append(s.getComponent(ref,com.hypixel.hytale.server.core.entity.UUIDComponent.getComponentType()).getUuid()).append(s.getComponent(ref,TransformComponent.getComponentType()).getPosition()).append(s.getComponent(ref,TransformComponent.getComponentType()).getRotation()).append(s.getComponent(ref,HeadRotation.getComponentType()).getRotation()).append(s.getComponent(ref,StateSupport.getComponentType()).getStateName());}return text.toString();}
 Ref<EntityStore>spawn(String role,Vector3d position){var pair=NPCPlugin.get().spawnNPC(s,role,null,position,Rotation3f.ZERO);require(pair!=null,"spawn failed "+role);return pair.first();}
 void label(String text,double x,double y,double z){var h=EntityStore.REGISTRY.newHolder();h.addComponent(TransformComponent.getComponentType(),new TransformComponent(new Vector3d(x,y,z),new Rotation3f()));h.addComponent(Nameplate.getComponentType(),new Nameplate(text));h.addComponent(ModelComponent.getComponentType(),new ModelComponent(com.hypixel.hytale.server.core.asset.type.model.config.Model.createStaticScaledModel(com.hypixel.hytale.server.core.asset.type.model.config.ModelAsset.getAssetMap().getAsset("Arrow_Iron"),.01f)));h.addComponent(com.hypixel.hytale.server.core.entity.Frozen.getComponentType(),com.hypixel.hytale.server.core.entity.Frozen.get());h.addComponent(com.hypixel.hytale.server.core.entity.UUIDComponent.getComponentType(),com.hypixel.hytale.server.core.entity.UUIDComponent.randomUUID());s.addEntity(h,AddReason.SPAWN);}
 void author(){for(var station:stations){for(int x=station.x()+1;x<=station.x()+4;x++)for(int y=64;y<=65;y++){require(NativeFieldBlocks.type(w,x,y,station.z()+1).getId().equals("Empty"),"wall would overwrite existing block");NativeFieldBlocks.set(w,x,y,station.z()+1,"Rock_Stone_Cobble");}var peer=spawn(peerRole(station),peerPosition(station));s.putComponent(peer,Nameplate.getComponentType(),new Nameplate("PEER - "+peerRole(station)));out("PEER_AUTHORED Role="+station.role()+" Position="+peerPosition(station)+" Yaw=0 WallX="+(station.x()+1)+".."+(station.x()+4)+" WallY=64..65 WallZ="+(station.z()+1));}}
 ItemContainer chest(Station a){var c=BlockModule.getComponent(ItemContainerBlock.getComponentType(),w,a.x(),64,a.z());require(c!=null&&c.getItemContainer()!=null,"missing chest "+a.role());return c.getItemContainer();}
 Ref<ChunkStore>ensureChest(int x,int z){var cs=w.getChunkStore();var section=cs.getChunkSectionReferenceAtBlock(x,64,z);var components=cs.getStore().getComponent(section,BlockComponentSection.getComponentType());return BlockEntity.ensureBlockEntity(cs.getStore(),section,components,x,64,z,NativeFieldBlocks.type(w,x,64,z),NativeFieldBlocks.section(w,x,64,z).getRotationIndex(x,64,z));}
 OwnershipProofData ownership(Station a){var r=BlockModule.getBlockEntity(w,a.x(),64,a.z());return w.getChunkStore().getStore().getComponent(r,OwnershipProofData.getComponentType());}
 Ref<EntityStore>geometryActor(){var k=roles.get("Kweebec_Sapling_HyThiefWitness");var h=EntityStore.REGISTRY.newHolder();h.addComponent(TransformComponent.getComponentType(),new TransformComponent(new Vector3d(0,64,0),new Rotation3f()));h.addComponent(com.hypixel.hytale.server.core.modules.physics.component.Velocity.getComponentType(),new com.hypixel.hytale.server.core.modules.physics.component.Velocity());h.addComponent(ModelComponent.getComponentType(),new ModelComponent(s.getComponent(k,ModelComponent.getComponentType()).getModel()));var box=s.getComponent(k,BoundingBox.getComponentType());if(box!=null)h.addComponent(BoundingBox.getComponentType(),(BoundingBox)box.clone());var movement=new MovementStatesComponent();movement.setMovementStates(new com.hypixel.hytale.protocol.MovementStates());h.addComponent(MovementStatesComponent.getComponentType(),movement);return s.addEntity(h,AddReason.SPAWN);}
 void verify()throws Exception{require(roles.size()==9&&peers.size()==5,"need original nine plus five peers");actor=geometryActor();int chests=0;for(int x=-64;x<64;x++)for(int z=-32;z<128;z++)for(int y=64;y<=68;y++)if(NativeFieldBlocks.type(w,x,y,z).getId().contains("Chest")&&NativeFieldBlocks.filler(w,x,y,z)==0)chests++;require(chests==9,"chest count changed");
  for(var station:stations){ensureChest(station.x(),station.z());var primary=roles.get(station.role());var peer=peers.get(station.role());for(var ref:List.of(primary,peer)){var expected=ref.equals(primary)?station.npc():peerPosition(station);require(s.getComponent(ref,TransformComponent.getComponentType()).getPosition().distance(expected)<.001,"pose");require(s.getComponent(ref,HeadRotation.getComponentType()).getRotation().yaw()==0&&s.getComponent(ref,TransformComponent.getComponentType()).getRotation().yaw()==0,"facing");require(s.getComponent(ref,WorldSupport.getComponentType()).getDefaultPlayerAttitude()==Attitude.FRIENDLY,"friendly");require(s.getComponent(ref,com.hypixel.hytale.server.core.entity.Frozen.getComponentType())==null,"frozen NPC");require(s.getComponent(ref,CombatSupport.getComponentType())!=null,"combat lost");}
   s.getComponent(actor,TransformComponent.getComponentType()).setPosition(station.pad());var visible=ContainerVisualWitness.evaluate(primary,actor,station.pad(),false,s);var hidden=ContainerVisualWitness.evaluate(peer,actor,station.pad(),false,s);require(visible.seen()&&visible.los()&&visible.distance()==8,"primary LOS broken "+visible.diagnostic());require(hidden.sector()&&!hidden.los()&&!hidden.seen()&&Math.abs(hidden.distance()-10)<.001,"peer not occluded "+hidden.diagnostic());
   for(int x=station.x()+1;x<=station.x()+4;x++)for(int y=64;y<=65;y++)require(NativeFieldBlocks.type(w,x,y,station.z()+1).getId().equals("Rock_Stone_Cobble"),"wall missing");
   var data=ownership(station);require(data.owned()&&data.scope().equals("FACTION")&&data.faction().equals(station.family()),"ownership");var c=chest(station);require(c.getItemStack((short)0).getQuantity()==16&&c.getItemStack((short)1).getQuantity()==8,"loot changed");var captured=ContainerVisualWitness.capture(actor,s,data,enabled(),this::out);require(captured.stream().filter(ContainerVisualWitness.Evidence::seen).count()==1&&captured.stream().filter(ContainerVisualWitness.Evidence::seen).allMatch(e->e.witness().equals(primary)),"hidden peer directly witnessed theft");double nearest=Double.POSITIVE_INFINITY;for(var other:stations)if(!other.role().equals(station.role()))for(var ref:List.of(roles.get(other.role()),peers.get(other.role()))){double d=s.getComponent(ref,TransformComponent.getComponentType()).getPosition().distance(station.pad());nearest=Math.min(nearest,d);require(d>20,"neighbor can witness");}safeActions(station,c);out("PEER_GEOMETRY_PASS Role="+station.role()+" PrimarySecondary=6.0 SecondaryChestOrigin="+peerPosition(station).distance(new Vector3d(station.x(),64,station.z()))+" SecondaryPad="+hidden.distance()+" PrimaryLOS="+visible.los()+" PeerLOS="+hidden.los()+" PeerFOV="+hidden.sector()+" NearestOtherStation="+nearest);}
  s.removeEntity(actor,RemoveReason.REMOVE);require(snapshotOriginal().equals(Files.readString(Path.of("original-area.sha256"))),"original changed during verification");out("ALL_PEER_FIXTURES_VALID NPCs=14 Chests=9 PrimaryPosesUnchanged=true OldAreaUnchanged=true");
 }
 void safeActions(Station a,ItemContainer c){var incoming=new SimpleItemContainer((short)4);incoming.setItemStackForSlot((short)0,new ItemStack("Ingredient_Fibre",3));var probe=new ContainerRemovalProbe(c,r->{throw new IllegalStateException("safe action counted as theft");},r->{});var one=c.registerChangeEvent(e->probe.source(e.transaction()));var two=incoming.registerChangeEvent(e->probe.receipt(e.transaction()));try{var section=w.getChunkStore().getChunkSectionReferenceAtBlock(a.x(),64,a.z());var base=NativeFieldBlocks.type(w,a.x(),64,a.z());require("Open_Container".equals(base.getInteractions().get(com.hypixel.hytale.protocol.InteractionType.Use)),"native chest Use replaced");for(String state:List.of("OpenWindow","CloseWindow"))com.hypixel.hytale.server.core.universe.world.chunk.BlockOperations.setBlockInteractionState(w.getChunkStore(),section,a.x(),64,a.z(),base,state,false);incoming.moveItemStackFromSlotToSlot((short)0,3,c,(short)5);c.moveItemStackFromSlotToSlot((short)5,3,c,(short)6);require(probe.finish()==0,"non-theft transaction");}finally{one.unregister();two.unregister();}out("SAFE_ACTIONS_PASS Role="+a.role()+" NativeOpenClose=true Deposit=true Rearrange=true FalseThefts=0");}
 String snapshotOriginal()throws Exception{var text=new StringBuilder();for(int x=-26;x<=26;x++)for(int z=-16;z<=26;z++)for(int y=63;y<=70;y++){var section=NativeFieldBlocks.section(w,x,y,z);text.append(x).append(',').append(y).append(',').append(z).append(':').append(NativeFieldBlocks.type(w,x,y,z).getId()).append(':').append(section.getFiller(x,y,z)).append(':').append(section.getRotationIndex(x,y,z)).append(';');}
  for(var name:new TreeSet<>(OLD)){var r=roles.get(name);require(r!=null,"original NPC absent");text.append(name).append(s.getComponent(r,TransformComponent.getComponentType()).getPosition()).append(s.getComponent(r,HeadRotation.getComponentType()).getRotation()).append(s.getComponent(r,StateSupport.getComponentType()).getStateName());}
  for(int z:new int[]{-6,-2,2,6}){var r=BlockModule.getBlockEntity(w,0,64,z);var data=w.getChunkStore().getStore().getComponent(r,OwnershipProofData.getComponentType());var inv=BlockModule.getComponent(ItemContainerBlock.getComponentType(),w,0,64,z).getItemContainer();text.append(data.owned()).append(data.scope()).append(data.faction());for(short n=0;n<inv.getCapacity();n++){var stack=inv.getItemStack(n);text.append(stack==null||stack.isEmpty()?"EMPTY":stack.getItemId()+":"+stack.getQuantity());}}
  var labels=new ArrayList<String>();s.forEachChunk(Nameplate.getComponentType(),(c,b)->{for(int i=0;i<c.size();i++){var r=c.getReferenceTo(i);var t=s.getComponent(r,TransformComponent.getComponentType());if(t!=null&&t.getPosition().x>=-26&&t.getPosition().x<=26&&t.getPosition().z>=-16&&t.getPosition().z<=26)labels.add(s.getComponent(r,Nameplate.getComponentType()).getText()+t.getPosition());}});Collections.sort(labels);for(var label:labels)text.append(label);return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(text.toString().getBytes(StandardCharsets.UTF_8)));
 }
 float health(){return s.getComponent(actor,EntityStatMap.getComponentType()).get(DefaultEntityStatTypes.getHealth()).get();}
 void schedule(){w.scheduleAfter(()->w.execute(()->{try{tick();}catch(Throwable e){fail(e);}}),250,TimeUnit.MILLISECONDS);}
 void tick()throws Exception{ticks++;int warmup=mode.equals("peer-idle")?240:16;
  if(ticks<=warmup){for(var station:stations)for(var ref:List.of(roles.get(station.role()),peers.get(station.role()))){var expected=ref.equals(roles.get(station.role()))?station.npc():peerPosition(station);double d=s.getComponent(ref,TransformComponent.getComponentType()).getPosition().distance(expected);double yaw=Math.abs(s.getComponent(ref,HeadRotation.getComponentType()).getRotation().yaw());double body=Math.abs(s.getComponent(ref,TransformComponent.getComponentType()).getRotation().yaw());maxIdleDistance=Math.max(maxIdleDistance,d);maxIdleYaw=Math.max(maxIdleYaw,Math.max(yaw,body));String state=s.getComponent(ref,StateSupport.getComponentType()).getStateName();idleStates.add(station.role()+":"+(ref.equals(roles.get(station.role()))?"primary":"peer")+":"+state);require(d<.001&&yaw<.001&&body<.001,"passive drift Role="+station.role()+" Peer="+ref.equals(peers.get(station.role()))+" Distance="+d+" Yaw="+yaw+" Body="+body);}}
  if(ticks==warmup)out("ALL_TEN_STATIONARY_PASS Seconds="+(warmup*.25)+" SamplesPerNPC="+warmup+" MaxPositionDrift="+maxIdleDistance+" MaxFacingDrift="+maxIdleYaw+" States="+idleStates);
  if(mode.equals("peer-idle")){if(ticks==warmup){finish("PEER_IDLE_PASS");return;}schedule();return;}
  var primary=roles.get(selected.role());var peer=peers.get(selected.role());
  if(ticks==warmup){var primarySight=ContainerVisualWitness.evaluate(primary,actor,selected.pad(),false,s);var peerSight=ContainerVisualWitness.evaluate(peer,actor,selected.pad(),false,s);require(primarySight.seen()&&!peerSight.los()&&!peerSight.seen(),"live before-theft LOS invalid");out("PRE_WITHDRAWAL_PRIMARY "+primarySight.diagnostic());out("PRE_WITHDRAWAL_SECONDARY "+peerSight.diagnostic());var c=chest(selected);var data=ownership(selected);safeActions(selected,c);var confirmed=new ArrayList<ContainerVisualWitness.Evidence>();var snaps=new IdentityHashMap<ContainerRemovalProbe.Removal,List<ContainerVisualWitness.Evidence>>();var receipts=new SimpleItemContainer((short)4);var probe=new ContainerRemovalProbe(c,r->confirmed.addAll(snaps.getOrDefault(r,List.of())),r->snaps.put(r,ContainerVisualWitness.capture(actor,s,data,enabled(),this::out)));var one=c.registerChangeEvent(e->probe.source(e.transaction()));var two=receipts.registerChangeEvent(e->probe.receipt(e.transaction()));try{c.moveItemStackFromSlotToSlot((short)0,1,receipts,(short)0);require(probe.finish()==1,"withdraw attribution");}finally{one.unregister();two.unregister();}require(confirmed.stream().filter(ContainerVisualWitness.Evidence::seen).count()==1&&confirmed.stream().filter(ContainerVisualWitness.Evidence::seen).allMatch(e->e.witness().equals(primary)),"non-primary witness");var messages=new ArrayList<com.hypixel.hytale.server.core.Message>();ContainerCaughtNotification.notifyWitnessed(confirmed,messages::add);int deliveries=HyThiefPersonalWitnessAlert.deliver(data,actor,confirmed,s,this::out);require(messages.size()==1,"message count");out("WITHDRAWAL_CONFIRMED PrimaryRole="+selected.role()+" Notifications=1 DirectHandoffs="+deliveries+" PeerNeverDirectlyDelivered=true");}
  if(ticks>warmup){String ps=s.getComponent(primary,StateSupport.getComponentType()).getStateName();String ss=s.getComponent(peer,StateSupport.getComponentType()).getStateName();boolean pt=actor.equals(s.getComponent(primary,MarkedEntitySupport.getComponentType()).getMarkedEntityRef("LockedTarget"));boolean st=actor.equals(s.getComponent(peer,MarkedEntitySupport.getComponentType()).getMarkedEntityRef("LockedTarget"));boolean pactive=pt&&(ps.startsWith("Combat")||ps.startsWith("Chase")||ps.startsWith("Converge"));boolean scombat=st&&(ss.startsWith("Combat")||ss.startsWith("Chase")||ss.startsWith("Converge")||ss.startsWith("Shoot"));boolean sactive=scombat||ss.startsWith("Investigate")||ss.startsWith("Search")||ss.startsWith("Alerted");if(pactive){primaryReacted=true;if(primaryFirst<0)primaryFirst=ticks;}if(sactive){peerReacted=true;peerAcquired=peerAcquired||st;if(peerFirst<0){peerFirst=ticks;out("SECONDARY_FIRST_ACQUISITION Role="+selected.role()+" State="+ss+" Seconds="+((ticks-warmup)*.25)+" "+ContainerVisualWitness.evaluate(peer,actor,selected.pad(),false,s).diagnostic());}}double pd=s.getComponent(primary,TransformComponent.getComponentType()).getPosition().distance(selected.npc());double sd=s.getComponent(peer,TransformComponent.getComponentType()).getPosition().distance(peerPosition(selected));primaryMaxDistance=Math.max(primaryMaxDistance,pd);peerMaxDistance=Math.max(peerMaxDistance,sd);var pos=s.getComponent(peer,TransformComponent.getComponentType()).getPosition();if(sactive&&sd>1&&ContainerVisualWitness.evaluate(peer,actor,selected.pad(),false,s).los())peerAroundWall=true;if(!ps.equals(previousPrimary)||!ss.equals(previousPeer)){out("NATIVE_STATE SecondsAfterTheft="+((ticks-warmup)*.25)+" Primary="+ps+" PrimaryTarget="+pt+" Secondary="+ss+" SecondaryTarget="+st+" SecondaryPosition="+pos);previousPrimary=ps;previousPeer=ss;}}
  if(ticks>warmup){for(var other:stations)if(!other.role().equals(selected.role()))for(var ref:List.of(roles.get(other.role()),peers.get(other.role())))require(!actor.equals(s.getComponent(ref,MarkedEntitySupport.getComponentType()).getMarkedEntityRef("LockedTarget")),"cross-station offender target "+other.role());}
  if(ticks>=warmup+120){out("FAMILY_RESULT Role="+selected.role()+" SecondaryRole="+peerRole(selected)+" PrimaryReacted="+primaryReacted+" PrimaryMovement="+primaryMaxDistance+" SecondaryReacted="+peerReacted+" SecondaryAcquiredOffender="+peerAcquired+" SecondaryMovement="+peerMaxDistance+" SecondaryPathToClearLOS="+peerAroundWall+" PrimaryReactionSeconds="+(primaryFirst<0?-1:(primaryFirst-warmup)*.25)+" SecondaryReactionSeconds="+(peerFirst<0?-1:(peerFirst-warmup)*.25)+" Damage="+(healthBefore-health())+" CustomGroupBroadcast=false");if(peerAcquired)require(peerMaxDistance>1&&peerAroundWall,"offender-alerted peer did not navigate wall");else if(!peerReacted)require(peerMaxDistance==0,"unalerted peer drifted");finish("PEER_RESPONSE_PASS");return;}schedule();
 }
 void finish(String status){out(status);try{Files.write(Path.of("field-evidence.txt"),evidence);}catch(Exception e){throw new RuntimeException(e);}CompletableFuture.runAsync(()->com.hypixel.hytale.server.core.HytaleServer.get().shutdownServer());}
 void fail(Throwable e){out("FAILED "+e);e.printStackTrace();finish("FAILED");}
}
